
.status-bar {
  max-width: 720px;
  margin: 0 auto;
  padding: 8px;
  background: var(--c-background);
  border: 1px solid var(--c-primary);
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.world-bar {
  display: flex;
  gap: 14px;
  padding: 4px 8px 8px;
  font-size: 12px;
  color: var(--c-text-muted);
  border-bottom: 1px dashed var(--c-border);
  margin-bottom: 8px;
}
